@js:
sort=[];
push=(title,url,type)=>{
		json = JSON.stringify({
				title: title,
				url: url?url:"",
				style: {
						layout_flexGrow: 1,
						layout_flexBasisPercent: type
					}
			});
		return sort.push(json);
	}
$$=(category_id,sex)=>`https://s30007.zhongyue001.com/book/index?category_id=${category_id}&sex=${sex}&page={{page}\}&type=category`;
[
		["男",[["都市",2],["玄幻",1],["仙侠",3],["奇幻",5],["历史",6],["军事",7],["科幻",9],["游戏",10]]],
