].map(([title,list],sex)=>{
		sex++;
		push('༺ˇ»`ʚ'+title+'频分类ɞ´«ˇ༻',null,1);
		list.map([title,category_id]=>{
				push(title,$$(category_id,sex),0.25);
			});
	});
'['+sort.toString()+']'

